const { itemType, commandFactory, getState, polySources } = options;
const state = getState();
const selectedRows = state.grid.selectedRows;
if (!selectedRows.length) {
	return;
}

const itemTypeMetadata = ArasModules.metadata.itemType;
const isPolymorphic = itemTypeMetadata.isPolymorphic(itemType.id);
const getItemType = (item) => {
	if (isPolymorphic) {
		const itemTypeId = item.itemtype;
		const itemTypeName = itemTypeMetadata.getItemTypeName(itemTypeId);
		return polySources[itemTypeName];
	}

	return itemType;
};
const rows = window.grid._grid.rows;
const canExecuteCommand = (commandAlias, action) => {
	const canExecute = selectedRows.every((selectedId) => {
		const item = rows.get(selectedId);
		const itemType = getItemType(item);
		const itemTypeName = itemType.name;
		const command = commandFactory(commandAlias, { item, itemType, itemTypeName });
		const commandEnabled = !window.isFunctionDisabled(itemTypeName, action);
		const canExecute = commandEnabled && command.canExecute();

		return canExecute;
	});

	return canExecute;
};
const executeCommand = (commandAlias, action) => {
	action = action.toLowerCase();

	const promises = selectedRows.map(async (rowId) => {
		const execInWin = window.execInTearOffWin(rowId, action);
		if (execInWin) {
			return null;
		}

		const item = rows.get(rowId);
		const itemType = getItemType(item);
		const itemTypeName = itemType.name;
		const command = commandFactory(commandAlias, { item, itemType, itemTypeName });
		return command.execute();
	});
	return Promise.allSettled(promises);
};
const claimAlias = target['command_alias@keyed_name'];
const claimAction = 'Lock';
const canClaimExecute = canExecuteCommand(claimAlias, claimAction);
if (canClaimExecute) {
	return executeCommand(claimAlias, claimAction);
}

const unclaimAlias = 'UnclaimItem';
const unclaimAction = 'Unlock';
const canUnclaimExecute = canExecuteCommand(unclaimAlias, unclaimAction);
if (canUnclaimExecute) {
	return executeCommand(unclaimAlias, unclaimAction);
}
